### 如果你使用的是 Unity C#

```csharp
using System.Collections.Generic;
using UnityEngine;

public class Node {
    public Vector2Int position;
    public bool walkable;
    public List<Node> neighbors;
    public int gCost, hCost;
    public Node parent;
    public int fCost => gCost + hCost;
}

public class Pathfinding {
    public List<Node> FindPath(Node startNode, Node goalNode) {
        var openSet = new List<Node> { startNode };
        var closedSet = new HashSet<Node>();

        while (openSet.Count > 0) {
            Node currentNode = openSet[0];
            for (int i = 1; i < openSet.Count; i++) {
                if (openSet[i].fCost < currentNode.fCost ||
                    openSet[i].fCost == currentNode.fCost && openSet[i].hCost < currentNode.hCost) {
                    currentNode = openSet[i];
                }
            }

            openSet.Remove(currentNode);
            closedSet.Add(currentNode);

            if (currentNode == goalNode) {
                return RetracePath(startNode, goalNode);
            }

            foreach (var neighbor in currentNode.neighbors) {
                if (!neighbor.walkable || closedSet.Contains(neighbor)) continue;

                int tentativeGCost = currentNode.gCost + GetDistance(currentNode, neighbor);
                if (tentativeGCost < neighbor.gCost || !openSet.Contains(neighbor)) {
                    neighbor.gCost = tentativeGCost;
                    neighbor.hCost = GetDistance(neighbor, goalNode);
                    neighbor.parent = currentNode;

                    if (!openSet.Contains(neighbor))
                        openSet.Add(neighbor);
                }
            }
        }

        return null; // 沒有路徑
    }

    private List<Node> RetracePath(Node startNode, Node endNode) {
        var path = new List<Node>();
        Node currentNode = endNode;

        while (currentNode != startNode) {
            path.Add(currentNode);
            currentNode = currentNode.parent;
        }
        path.Reverse();
        return path;
    }

    private int GetDistance(Node a, Node b) {
        int dstX = Mathf.Abs(a.position.x - b.position.x);
        int dstY = Mathf.Abs(a.position.y - b.position.y);
        return dstX + dstY; // 曼哈頓距離
    }
}
```

